        let packed_chats = self
            .table
            .get_all_rows()
            .values()
            .filter_map(|row| {
                PackedBlacklistedUser::new(row.row_data.belongs_to, row.row_data.seen_by.clone())
            })
            .collect();

        save_blacklisted_users(packed_chats, overwrite);
    }

